import os,pty,subprocess
def run(args, timeout=10, env=None, cwd='/tmp/t/cli'):
    """stdin = pty (tty), stdout/stderr = pipes."""
    m,s=pty.openpty()
    e=dict(os.environ)
    if env:
        for k,v in env.items():
            if v is None: e.pop(k,None)
            else: e[k]=v
    p=subprocess.Popen(['/workspace/executable']+args,stdin=s,stdout=subprocess.PIPE,stderr=subprocess.PIPE,cwd=cwd,env=e)
    os.close(s)
    try:
        o,er=p.communicate(timeout=timeout); rc=p.returncode
    except subprocess.TimeoutExpired:
        p.kill(); o,er=p.communicate(); rc='TIMEOUT'
    os.close(m)
    return rc,o,er
